"use client";

import {
    Users,
    Search,
    MoreVertical,
    Mail,
    Phone,
    Shield,
    Plus,
    ArrowRight,
    Filter
} from "lucide-react";
import { cn } from "@/lib/utils";
import { useState } from "react";
import { useSimulation } from "@/components/SimulationProvider";
import useSWR from "swr";
import { fetcher } from "@/lib/fetcher";

export default function CustomersPage() {
    const { currentUser } = useSimulation();
    const { data: customers, error } = useSWR(`/api/customers?seller=${currentUser.role === 'admin' ? 'admin' : currentUser.name}`, fetcher);
    const [searchTerm, setSearchTerm] = useState("");

    const filteredCustomers = (customers || []).filter((customer: any) =>
        customer.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        customer.doc.includes(searchTerm) ||
        customer.email.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div className="p-4 lg:p-8 space-y-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-2xl font-black mb-1">Clientes</h1>
                    <p className="text-xs text-slate-500 font-medium uppercase tracking-wider">Gestão da Base e Fidelização</p>
                </div>
                <button className="bg-primary text-white px-6 py-2.5 rounded-xl font-bold text-xs flex items-center gap-2 shadow-lg shadow-primary/20 hover:scale-[1.02] transition-all self-start md:self-auto">
                    <Plus size={16} />
                    Novo Cliente
                </button>
            </div>

            <div className="bg-white dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-800 p-4 shadow-sm">
                <div className="flex flex-col md:flex-row gap-4">
                    <div className="relative flex-1">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                        <input
                            type="text"
                            placeholder="Buscar cliente por nome, documento ou e-mail..."
                            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 dark:bg-slate-900 border-none rounded-xl text-sm focus:ring-2 focus:ring-primary transition-all"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    </div>
                    <button className="px-4 py-2 bg-slate-100 dark:bg-slate-700 hover:bg-slate-200 rounded-xl text-xs font-bold transition-all flex items-center gap-2">
                        <Filter size={16} />
                        Segmentação
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {!customers && !error && <p className="col-span-full text-center text-slate-400 py-20 italic">Carregando base de clientes...</p>}
                {filteredCustomers.map((customer: any) => (
                    <div key={customer.id} className="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-800 overflow-hidden shadow-sm hover:shadow-md transition-shadow group">
                        <div className="p-6">
                            <div className="flex justify-between items-start mb-4">
                                <div className="size-12 rounded-2xl bg-primary/10 flex items-center justify-center text-primary font-bold text-lg">
                                    {customer.name.charAt(0)}
                                </div>
                                <button className="p-1.5 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg">
                                    <MoreVertical size={18} />
                                </button>
                            </div>

                            <div className="space-y-1 mb-6">
                                <h3 className="text-lg font-bold truncate">{customer.name}</h3>
                                <p className="text-xs text-slate-500 font-medium tracking-tight">{customer.doc}</p>
                            </div>

                            <div className="space-y-3 mb-6">
                                <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400">
                                    <Mail size={14} className="text-primary" />
                                    <span className="text-xs truncate">{customer.email}</span>
                                </div>
                                <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400">
                                    <Phone size={14} className="text-primary" />
                                    <span className="text-xs">{customer.phone}</span>
                                </div>
                            </div>

                            <div className="flex items-center justify-between pt-4 border-t border-slate-50 dark:border-slate-800">
                                <div className="flex items-center gap-1.5">
                                    <Shield size={14} className={customer.has_certificate ? "text-emerald-500" : "text-slate-300"} />
                                    <span className={cn(
                                        "text-[10px] font-bold uppercase",
                                        customer.has_certificate ? "text-emerald-600" : "text-slate-400"
                                    )}>
                                        {customer.has_certificate ? "Ativo" : "Sem Certificado"}
                                    </span>
                                </div>
                                <p className="text-xs font-bold text-slate-900 dark:text-white">
                                    {customer.total_spent.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                                </p>
                            </div>
                        </div>

                        <button className="w-full bg-slate-50 dark:bg-slate-900/50 py-3 text-[10px] font-bold uppercase tracking-widest text-primary flex items-center justify-center gap-2 hover:bg-primary hover:text-white transition-all">
                            Ver Histórico Completo
                            <ArrowRight size={14} />
                        </button>
                    </div>
                ))}
            </div>
        </div>
    );
}
